/**
 * Pooled 3D Mesh VFX renderer for `renderMode: 'mesh'` layers (shields, ice lances, shock domes).
 * Supports custom GLBs, built-in geometries, UV scrolling, Fresnel rim glow, and procedural dissolve.
 * @param {object} [options]
 * @param {string} [options.mode='headless']
 * @param {object | null} [options.THREE=null]
 * @param {object | null} [options.scene=null]
 * @param {number} [options.maxMeshes=64]
 */
export function createMeshVfxPool({ mode, THREE, scene, maxMeshes, }?: {
    mode?: string | undefined;
    THREE?: object | null;
    scene?: object | null;
    maxMeshes?: number | undefined;
} | undefined): {
    capacity: number;
    registerMesh: (id: string, geometryOrObject3D: object, options?: {}) => boolean;
    registerUberMaterial: (matSpec: any) => any;
    getSurfaceSamples: (name: any) => any;
    spawn: (opts?: object) => number;
    killSlot: (slotIdx: any) => void;
    readSlotMotion: (slotIdx: any, position: any, velocity: any) => void;
    readSlotTransform: (slotIdx: any, position: any, quatOut: any, scaleOut: any, t?: number) => boolean;
    updateSlot: (slotIdx: any, x: any, y: any, z: any, vx: any, vy: any, vz: any) => void;
    setWind: (wx?: number, wy?: number, wz?: number) => void;
    setCamera: (camera: any) => void;
    setEffectOffset: (slotIdx: any, x?: number, y?: number, z?: number) => void;
    setAtlas: (textureOrCanvas: any, newRegions: any, options?: {}) => void;
    setDepthTexture: (depthTexture: any, { near, far, width, height, softFade }?: {
        near?: number | undefined;
        far?: number | undefined;
        width?: number | undefined;
        height?: number | undefined;
        softFade?: number | undefined;
    }) => void;
    setSceneTexture: (sceneTexture: object | null, { width, height }?: {
        width?: number;
        height?: number;
    } | undefined) => void;
    setQualityTier: (tier?: string) => void;
    hasActiveDistortion: () => boolean;
    update: (visualDt: any) => void;
    reset: () => void;
    dispose: () => void;
    getStats(): {
        capacity: number;
        activeCount: number;
        instancedBatches: number;
        totalSpawned: number;
        registeredMeshes: number;
    };
};
export const VFX_MESH_VERTEX_GLSL: "\nuniform vec2 uUvScroll;\nuniform vec4 uUvST;\nuniform vec3 uPivot;\nuniform float uTime;\n\nvarying vec2 vUv;\nvarying vec3 vNormalView;\nvarying vec3 vViewPos;\nvarying vec3 vLocalPos;\n\nvoid main() {\n  vUv = uv * uUvST.xy + uUvST.zw + uUvScroll * uTime;\n  vec3 shiftedPos = position - uPivot;\n  vLocalPos = shiftedPos;\n  vNormalView = normalize(normalMatrix * normal);\n  vec4 mvPos = modelViewMatrix * vec4(shiftedPos, 1.0);\n  vViewPos = -mvPos.xyz;\n  gl_Position = projectionMatrix * mvPos;\n}\n";
export const VFX_MESH_FRAGMENT_GLSL: "\nprecision highp float;\n\nuniform sampler2D uTex;\nuniform float uHasTex;\nuniform vec4 uTexRect;\nuniform float uAtlasUv;\nuniform float uFlipLocalV;\nuniform vec4 uFlipbook;\nuniform float uLifeRatio;\nuniform sampler2D uSceneTex;\nuniform float uHasSceneTex;\nuniform sampler2D uSoftDepthTex;\nuniform float uHasSoftDepth;\nuniform float uSoftFade;\nuniform vec2 uCamNearFar;\nuniform float uDistortion;\nuniform float uIsMultiply;\nuniform float uOpaque;\nuniform float uAlphaCutoff;\nuniform vec2 uCameraFade;\nuniform vec2 uInvViewport;\nuniform vec3 uColor;\nuniform float uOpacity;\nuniform float uHdr;\nuniform float uLit;\nuniform vec3 uLightDirView;\nuniform vec3 uEmission;\nuniform vec2 uFresnel;     // power, intensity\nuniform vec3 uDissolve;    // progress [0..1], edgeWidth, enabled\nuniform vec3 uDissolveColor;\nuniform vec4 uCustom1;\nuniform vec4 uCustom2;\n\nvarying vec2 vUv;\nvarying vec3 vNormalView;\nvarying vec3 vViewPos;\nvarying vec3 vLocalPos;\n\nfloat hash31(vec3 p) {\n  p = fract(p * 0.1031);\n  p += dot(p, p.yzx + 33.33);\n  return fract((p.x + p.y) * p.z);\n}\n\nfloat valueNoise3(vec3 x) {\n  vec3 i = floor(x);\n  vec3 f = fract(x);\n  f = f * f * (3.0 - 2.0 * f);\n  return mix(\n    mix(mix(hash31(i + vec3(0,0,0)), hash31(i + vec3(1,0,0)), f.x),\n        mix(hash31(i + vec3(0,1,0)), hash31(i + vec3(1,1,0)), f.x), f.y),\n    mix(mix(hash31(i + vec3(0,0,1)), hash31(i + vec3(1,0,1)), f.x),\n        mix(hash31(i + vec3(0,1,1)), hash31(i + vec3(1,1,1)), f.x), f.y),\n    f.z\n  );\n}\n\n\nfloat vfxLinearizeDepth(float zNdc, vec2 camNearFar) {\n  float z = zNdc * 2.0 - 1.0;\n  float n = camNearFar.x;\n  float f = camNearFar.y;\n  return (2.0 * n * f) / max(0.0001, f + n - z * (f - n));\n}\n\nfloat vfxComputeSoftFade(\n  sampler2D depthTex,\n  float hasDepth,\n  vec2 fragCoord,\n  vec2 invViewport,\n  vec2 camNearFar,\n  float fragDepthZ,\n  float softFade\n) {\n  if (hasDepth < 0.5 || softFade <= 0.0001) return 1.0;\n  float sceneDepthRaw = texture2D(depthTex, fragCoord * invViewport).r;\n  float sceneZ = vfxLinearizeDepth(sceneDepthRaw, camNearFar);\n  float partZ = vfxLinearizeDepth(fragDepthZ, camNearFar);\n  return clamp((sceneZ - partZ) / max(0.0001, softFade), 0.0, 1.0);\n}\n\nvec4 vfxChannelPicker(vec4 rgba, vec4 mask) {\n  return rgba * mask;\n}\n\nfloat vfxChannelPickerAdd(vec4 rgba, vec4 mask) {\n  return clamp(dot(rgba, mask), 0.0, 1.0);\n}\n\nfloat vfxChannelPickerClamped(vec4 rgba, vec4 mask) {\n  return clamp(dot(clamp(rgba * mask, 0.0, 1.0), vec4(1.0)), 0.0, 1.0);\n}\n\nvec3 vfxSrgbToLinear3(vec3 c) {\n  vec3 linLo = c / 12.92;\n  vec3 linHi = pow(max((c + vec3(0.055)) / 1.055, vec3(1e-5)), vec3(2.4));\n  vec3 mask = step(vec3(0.04045), c);\n  return mix(linLo, linHi, mask);\n}\n\nvec3 vfxDesaturate(vec3 rgb, float amt) {\n  const vec3 lumaW = vec3(0.2126729, 0.7151522, 0.0721750);\n  float luma = dot(rgb, lumaW);\n  return mix(rgb, vec3(luma), clamp(amt, 0.0, 1.0));\n}\n\nfloat vfxSafeSmoothstep(float e0, float e1, float x) {\n  float d = e1 - e0;\n  float sd = abs(d) < 1e-5 ? (d < 0.0 ? -1e-5 : 1e-5) : d;\n  float t = clamp((x - e0) / sd, 0.0, 1.0);\n  return t * t * (3.0 - 2.0 * t);\n}\n\nbool vfxHasFlag(float flags, float bitVal) {\n  float cleanFlags = floor(flags + 0.5);\n  return mod(floor(cleanFlags / bitVal), 2.0) > 0.5;\n}\n\nvec2 vfxPolarCoords(vec2 uv, vec2 center) {\n  vec2 d = uv - center;\n  float r = length(d) * 2.0;\n  float ang = atan(d.y, d.x) * 0.15915494309 + 0.5;\n  return vec2(r, ang);\n}\n\nvec4 vfxSampleAtlasRectWrapped(sampler2D atlasTex, vec4 rect, vec2 uv, float flipV, bool clampU, bool clampV) {\n  vec2 halfTex = clamp(vec2(0.5) / max(vec2(1.0), abs(rect.zw - rect.xy) * 4096.0), vec2(0.001), vec2(0.25));\n  vec2 tiled = vec2(\n    clampU ? clamp(uv.x, halfTex.x, 1.0 - halfTex.x) : fract(uv.x),\n    clampV ? clamp(uv.y, halfTex.y, 1.0 - halfTex.y) : fract(uv.y)\n  );\n  vec2 mapped = vec2(\n    mix(rect.x, rect.z, tiled.x),\n    mix(rect.y, rect.w, tiled.y)\n  );\n  if (flipV > 0.5) mapped.y = 1.0 - mapped.y;\n  return texture2D(atlasTex, mapped);\n}\n\nvec4 vfxSampleAtlasRect(sampler2D atlasTex, vec4 rect, vec2 uv, float flipV) {\n  return vfxSampleAtlasRectWrapped(atlasTex, rect, uv, flipV, false, false);\n}\n\n\nvec2 vfxFlipbookGrid(vec2 tiles) {\n  return max(vec2(1.0), floor(tiles + 0.5));\n}\n\nfloat vfxFlipbookFramePosition(float lifeRatio, vec2 grid, float cycles) {\n  float total = grid.x * grid.y;\n  cycles = max(0.01, cycles);\n  float phase = lifeRatio * cycles;\n  if (phase >= 1.0 && cycles <= 1.001) return total - 0.001;\n  return min(fract(phase), 0.9999) * total;\n}\n\nvec2 vfxFlipbookFrameUv(float frameIndex, vec2 localUv, vec2 grid) {\n  vec2 cell = vec2(mod(frameIndex, grid.x), floor(frameIndex / grid.x));\n  return (cell + localUv) / grid;\n}\n\n\n// Splits uv0 into flipbook cell coordinates (supports top-down grid + rowMode random/custom).\n// Returns (uvA, uvB) packed in vec4; meta.z = frame index, meta.w = next-frame blend.\nvec4 vfxComputeFlipbookUvPair(vec2 uv0, vec4 flipbookGridInfo, float frameIndex) {\n  vec2 grid = max(vec2(1.0), floor(flipbookGridInfo.xy + 0.5));\n  if (grid.x <= 1.0 && grid.y <= 1.0) {\n    return vec4(uv0, uv0);\n  }\n  float total = grid.x * grid.y;\n  float f0 = clamp(floor(frameIndex), 0.0, total - 1.0);\n  float f1 = min(f0 + 1.0, total - 1.0);\n  float col0 = mod(f0, grid.x);\n  float row0 = floor(f0 / grid.x);\n  float col1 = mod(f1, grid.x);\n  float row1 = floor(f1 / grid.x);\n  // Flip V inside cell so Unity top-left flipbook grid maps cleanly to OpenGL UV (bottom-up).\n  vec2 cellUvA = vec2((col0 + uv0.x) / grid.x, 1.0 - (row0 + 1.0 - uv0.y) / grid.y);\n  vec2 cellUvB = vec2((col1 + uv0.x) / grid.x, 1.0 - (row1 + 1.0 - uv0.y) / grid.y);\n  return vec4(cellUvA, cellUvB);\n}\n\nvec3 vfxEvalUberRamp(\n  vec3 satMain,\n  vec3 lastColor,\n  vec3 midColor,\n  vec3 whiteColor,\n  float midHigh,\n  float midLow\n) {\n  float v = clamp(satMain.r, 0.0, 1.0);\n  float denom = max(1e-5, abs(1.0 - midHigh)) * (1.0 - midHigh < 0.0 ? -1.0 : 1.0);\n  float remappedHigh = clamp(v - midHigh, 0.0, 1.0) / denom;\n  float remappedLow = (v * (remappedHigh - midLow)) / denom;\n  vec3 lo = mix(lastColor, midColor, remappedLow);\n  vec3 hi = mix(midColor, whiteColor, remappedHigh);\n  return max(vec3(0.0), mix(lo, hi, v));\n}\n\nvec4 vfxFinalizeOutput(vec4 res, float isOpaque, float isMultiply, float isPremultiply, float isAdditive) {\n  if (isOpaque > 0.5) {\n    return vec4(res.rgb, 1.0);\n  }\n  if (isMultiply > 0.5) {\n    return vec4(mix(vec3(1.0), res.rgb, clamp(res.a, 0.0, 1.0)), 1.0);\n  }\n  if (isPremultiply > 0.5) {\n    return res;\n  }\n  vec3 outRgb = res.rgb;\n  float outA = res.a;\n  float peak = max(outRgb.r, max(outRgb.g, outRgb.b));\n  if (isAdditive > 0.5 && peak > 1.0 && outA > 0.0 && outA < 1.0) {\n    float boost = min(peak, 1.0 / outA);\n    outRgb /= boost;\n    outA *= boost;\n  }\n  return vec4(outRgb, outA);\n}\n\n\nvec4 sampleAtlas(vec2 localUv) {\n  vec2 texUv = mix(uTexRect.xy, uTexRect.zw, localUv);\n  if (uAtlasUv > 1.5) texUv.y = 1.0 - texUv.y;\n  return texture2D(uTex, texUv);\n}\n\nvec4 sampleParticleTexture() {\n  if (uHasTex < 0.5) return vec4(1.0);\n  vec2 localUv = fract(vUv);\n  if (uAtlasUv < 0.5) return texture2D(uTex, localUv);\n  if (uFlipLocalV > 0.5) localUv.y = 1.0 - localUv.y;\n  if (uFlipbook.x < 1.5 && uFlipbook.y < 1.5) return sampleAtlas(localUv);\n\n  vec2 grid = vfxFlipbookGrid(uFlipbook.xy);\n  float frame = vfxFlipbookFramePosition(uLifeRatio, grid, uFlipbook.z);\n  float first = floor(frame);\n  vec4 color = sampleAtlas(vfxFlipbookFrameUv(first, localUv, grid));\n  if (uFlipbook.w > 0.5) {\n    float next = min(first + 1.0, grid.x * grid.y - 1.0);\n    color = mix(color, sampleAtlas(vfxFlipbookFrameUv(next, localUv, grid)), fract(frame));\n  }\n  return color;\n}\n\nvoid main() {\n  vec4 texCol = sampleParticleTexture();\n  vec3 N = normalize(vNormalView);\n  vec3 V = normalize(vViewPos);\n  float alpha = texCol.a * uOpacity;\n  if (uDistortion > 0.5) {\n    if (uHasSceneTex < 0.5 || alpha < uAlphaCutoff) discard;\n    float ndotv = clamp(abs(dot(N, V)), 0.0, 1.0);\n    float dAlpha = alpha * smoothstep(0.0, 0.28, ndotv);\n    if (dAlpha < 0.005) discard;\n    vec2 nOff = (uHasTex > 0.5) ? (texCol.rg * 2.0 - 1.0) : (N.xy * ndotv);\n    vec2 screenUv = gl_FragCoord.xy * uInvViewport;\n    vec2 refrUv = clamp(screenUv + nOff * 0.038 * dAlpha, vec2(0.002), vec2(0.998));\n    gl_FragColor = vec4(texture2D(uSceneTex, refrUv).rgb, clamp(dAlpha, 0.0, 1.0));\n    return;\n  }\n\n  vec3 baseCol = texCol.rgb * uColor * max(0.0, uHdr) * max(0.0, uCustom1.x + 1.0);\n  if (uLit > 0.5) {\n    vec3 L = normalize(uLightDirView);\n    float ndotl = max(dot(N, L), 0.0);\n    float hemi = 0.5 + 0.5 * N.y;\n    vec3 H = normalize(L + V);\n    float spec = pow(max(dot(N, H), 0.0), 28.0) * 0.45;\n    baseCol = baseCol * (0.35 + 0.45 * hemi + 0.65 * ndotl) + vec3(spec) * uColor;\n  }\n  baseCol += texCol.rgb * uEmission;\n\n  if (uFresnel.y > 0.001) {\n    float ndotv = clamp(abs(dot(N, V)), 0.0, 1.0);\n    float rim = pow(1.0 - ndotv, max(0.25, uFresnel.x)) * uFresnel.y;\n    baseCol += uColor * (rim * max(1.0, uHdr));\n    alpha = clamp(alpha + rim * uOpacity, 0.0, 1.0);\n  }\n\n  if (uDissolve.z > 0.5) {\n    float n = valueNoise3(vLocalPos * 4.5 + vec3(0.0, vUv.y * 2.0, 0.0));\n    float cut = uDissolve.x;\n    if (n < cut) discard;\n    float edge = 1.0 - smoothstep(cut, cut + max(0.02, uDissolve.y), n);\n    baseCol = mix(baseCol, uDissolveColor * max(1.5, uHdr), edge);\n  }\n\n  if (alpha < uAlphaCutoff) discard;\n  float camFade = (uCameraFade.y > uCameraFade.x + 0.001)\n    ? clamp((abs(vViewPos.z) - uCameraFade.x) / (uCameraFade.y - uCameraFade.x), 0.0, 1.0)\n    : 1.0;\n  float softMul = vfxComputeSoftFade(uSoftDepthTex, uHasSoftDepth, gl_FragCoord.xy, uInvViewport, uCamNearFar, gl_FragCoord.z, uSoftFade);\n  alpha = uOpaque > 0.5 ? 1.0 : alpha * camFade * softMul;\n  if (alpha < 0.005) discard;\n  if (uIsMultiply > 0.5) {\n    gl_FragColor = vec4(mix(vec3(1.0), baseCol, clamp(alpha, 0.0, 1.0)), 1.0);\n    return;\n  }\n  gl_FragColor = vec4(baseCol, alpha);\n}\n";
